export interface IuSoftIconProps extends Omit<React.SVGProps<SVGSVGElement>, "name"> {
  name: IuSoftIconName;
  variant?: IuSoftIconVariant;
  surface?: IuSoftIconSurface;
  size?: number | string;
  strokeWidth?: number | string;
  animate?: "hover" | "none";
}

interface GlassGeometry {
  back: string[];
  glass: string;
  inner?: string;
  bevel?: string;
  front: string[];
  y1: number;
  y2: number;
}

interface IconVariants {
  glass: GlassGeometry;
  outline: string;
  solid: string;
  duotone: string;
}

